vRtrMplsLspRsvpAdspec = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 6, 1, 1, 29), TruthValue().clone('false')).setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrMplsLspRsvpAdspec.setStatus('current')
if mibBuilder.loadTexts: vRtrMplsLspRsvpAdspec.setDescription("When the value of vRtrMplsLspRsvpAdspec is 'true', the ADSPEC object\n         will be included in RSVP messages. When the value of\n         vRtrMplsLspRsvpAdspec is 'false', the ADSPEC object will not be\n         included in RSVP messages.")
vRtrMplsLspFRMethod = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 6, 1, 1, 30), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("oneToOneBackup", 1), ("facilityBackup", 2))).clone('oneToOneBackup')).setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrMplsLspFRMethod.setStatus('current')
if mibBuilder.loadTexts: vRtrMplsLspFRMethod.setDescription("The value of vRtrMplsLspFRMethod specifies the fast reroute method\n         used.\n\n         In the 'One-to-one Backup' method, a backup LSP is established which\n         will intersect the original LSP somewhere downstream of the point of\n         link or node failure. For each LSP that is backed up, a separate\n         backup LSP is established.\n\n         In the 'Facility Backup' method, instead of creating a separate LSP\n         for every LSP that is to be backed up, a single LSP is created which\n         serves as a backup for a set of LSPs. Such an LSP tunnel is called a\n         'bypass tunnel'.")
vRtrMplsLspFRNodeProtect = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 6, 1, 1, 31), TruthValue().clone('true')).setMaxAccess("readcreate")
