vRtrMplsGeneralBypassResigTimer = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 6, 7, 1, 43), Unsigned32().subtype(subtypeSpec=ConstraintsUnion(ValueRangeConstraint(0, 0), ValueRangeConstraint(30, 10080), )).clone(0)).setUnits('minutes').setMaxAccess("readcreate")
