vRtrMplsLspTemplateMetric = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 6, 41, 1, 29), Unsigned32().subtype(subtypeSpec=ConstraintsUnion(ValueRangeConstraint(0, 0), ValueRangeConstraint(1, 16777215), )).clone(0)).setMaxAccess("readcreate")
