vRtrMplsLspTemplateHoldPriority = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 6, 41, 1, 31), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(0, 7)).clone(0)).setMaxAccess("readcreate")
